import {normalizeFraming,frameCanvas,framingGeometry,ratioFraming} from './framing.js';
export function mountFraming({getState,canEdit,checkpoint,onChange}){
 const $=id=>document.getElementById(id),button=document.createElement('button');button.type='button';button.id='framingButton';button.className='button outline full';button.textContent='Recortar / girar';
 $('editControlsPanel').querySelector('.adjustments-heading').after(button);
 const dialog=document.createElement('dialog');dialog.id='framingDialog';dialog.className='framing-dialog';
 dialog.innerHTML=`<button type="button" class="dialog-close" aria-label="Cerrar">×</button><span class="eyebrow">ENCUADRE</span><h2>Recortar y enderezar</h2><p>Arrastrá el encuadre o sus esquinas. El original se conserva.</p><div class="framing-stage"><canvas id="framingCanvas"></canvas><div id="framingBox"><i data-corner="nw"></i><i data-corner="ne"></i><i data-corner="sw"></i><i data-corner="se"></i></div></div><div class="framing-tools"><label class="field">Formato<select id="framingRatio"><option value="0">Libre</option><option value="1">1:1 · Cuadrado</option><option value="0.8">4:5 · Retrato</option><option value="1.7777777778">16:9 · Horizontal</option><option value="0.5625">9:16 · Vertical</option><option value="1.5">3:2 · Fotografía</option></select></label><button type="button" id="framingTurn" class="button outline">↻ Girar 90°</button></div><label class="field">Enderezar <output id="framingAngleValue">0°</output><input id="framingAngle" type="range" min="-20" max="20" step="0.1" value="0"></label><details><summary>Encuadre preciso (%)</summary><div class="framing-numbers">${[['x','Izquierda'],['y','Arriba'],['width','Ancho'],['height','Alto']].map(([key,label])=>`<label class="field">${label}<input id="framing-${key}" type="number" min="${key==='width'||key==='height'?5:0}" max="100" step="0.1"></label>`).join('')}</div></details><p id="framingDimensions" class="tiny muted"></p><div class="framing-actions"><button type="button" id="framingReset" class="text-button">Restablecer encuadre</button><button type="button" id="framingApply" class="button dark">Aplicar encuadre</button></div>`;
 document.body.append(dialog);let draft=null,source=null,drag=null,drawn=null;
 const full=()=>({turns:0,angle:0,x:0,y:0,width:1,height:1});
 function selection(){const g=framingGeometry(getState().width||source.width,getState().height||source.height,draft),box=$('framingBox');Object.assign(box.style,{left:draft.x*100+'%',top:draft.y*100+'%',width:draft.width*100+'%',height:draft.height*100+'%'});for(const key of ['x','y','width','height'])$('framing-'+key).value=+(draft[key]*100).toFixed(1);$('framingDimensions').textContent=`Salida original: ${g.outputWidth} × ${g.outputHeight} px · sin ampliar la foto`;$('framingAngle').value=draft.angle;$('framingAngleValue').textContent=draft.angle.toFixed(1)+'°';}
 function paint(){if(drawn&&drawn!==source)drawn.width=drawn.height=0;drawn=frameCanvas(source,{...draft,x:0,y:0,width:1,height:1});const canvas=$('framingCanvas');canvas.width=drawn.width;canvas.height=drawn.height;canvas.getContext('2d').drawImage(drawn,0,0);selection();}
 function close(){dialog.close();drag=null;if(source)source.width=source.height=0;if(drawn&&drawn!==source)drawn.width=drawn.height=0;source=drawn=null;}
 button.onclick=()=>{if(!canEdit()||getState().videoMedia)return;const state=getState();source=document.createElement('canvas');source.width=state.preview.width;source.height=state.preview.height;source.getContext('2d').putImageData(state.preview,0,0);draft={...full(),...(normalizeFraming(state.settings.framing)||{})};$('framingRatio').value='0';paint();dialog.showModal();};
 dialog.querySelector('.dialog-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
 $('framingRatio').onchange=()=>{draft=ratioFraming(source.width,source.height,Number($('framingRatio').value),draft);selection();};
 $('framingTurn').onclick=()=>{draft={...draft,turns:(draft.turns+1)%4,x:0,y:0,width:1,height:1};draft=ratioFraming(source.width,source.height,Number($('framingRatio').value),draft);paint();};
 $('framingAngle').oninput=e=>{draft.angle=Number(e.target.value);paint();};$('framingReset').onclick=()=>{draft=full();$('framingRatio').value='0';paint();};
 for(const key of ['x','y','width','height'])$('framing-'+key).onchange=e=>{draft={...full(),...(normalizeFraming({...draft,[key]:Number(e.target.value)/100})||{})};$('framingRatio').value='0';selection();};
 const box=$('framingBox');box.addEventListener('pointerdown',e=>{if(e.button>0)return;e.preventDefault();box.setPointerCapture?.(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,start:{...draft},corner:e.target.dataset.corner,rect:$('framingCanvas').getBoundingClientRect()};});
 box.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;e.preventDefault();const d=drag,start=d.start,dx=(e.clientX-d.x)/d.rect.width,dy=(e.clientY-d.y)/d.rect.height,clamp=(v,a,b)=>Math.max(a,Math.min(b,v));if(!d.corner){draft={...draft,x:clamp(start.x+dx,0,1-start.width),y:clamp(start.y+dy,0,1-start.height)};}else{const west=d.corner.includes('w'),north=d.corner.includes('n'),anchorX=west?start.x+start.width:start.x,anchorY=north?start.y+start.height:start.y;let width=clamp(start.width+(west?-dx:dx),.05,west?anchorX:1-anchorX),height=clamp(start.height+(north?-dy:dy),.05,north?anchorY:1-anchorY);const ratio=Number($('framingRatio').value);if(ratio){const g=framingGeometry(source.width,source.height,draft),relative=ratio*g.orientedHeight/g.orientedWidth;const maxH=north?anchorY:1-anchorY;height=Math.min(width/relative,maxH);width=height*relative;}draft={...draft,x:west?anchorX-width:anchorX,y:north?anchorY-height:anchorY,width,height};}selection();});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])box.addEventListener(event,()=>drag=null);
 $('framingApply').onclick=()=>{if(!canEdit()){close();return;}checkpoint();getState().settings.framing=normalizeFraming(draft);close();onChange();};
 function sync(){button.disabled=!canEdit()||!!getState().videoMedia;button.textContent=normalizeFraming(getState().settings.framing)?'Editar encuadre':'Recortar / girar';}
 return {sync};
}
